347	    private static boolean isBlank(String value) {
348	        return value == null || value.trim().isEmpty();
349	    }
350	
351	    /**
352	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
353	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
354	     * compared case-insensitively with collapsed whitespace.
355	     */
356	    private static String collapse(String value) {
357	        if (value == null) {
358	            return "";
359	        }
360	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
361	    }
362	
363	    /**
364	     * Common street-type abbreviations expanded during address normalization.
365	     */
366	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
367	        "ST", "STREET",
368	        "RD", "ROAD",
369	        "AVE", "AVENUE");
370	
371	    /**
372	     * Normalize an owner address into its canonical stored/compared form: trim, collapse every run
373	     * of whitespace to a single space, upper-case, and expand common street-type abbreviations
374	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). Returns an empty string for
375	     * a {@code null} or blank input. The transformation is idempotent, so an already-normalized
376	     * address maps to itself.
377	     */
378	    private static String normalizeAddress(String value) {
379	        if (value == null) {
380	            return "";
381	        }
382	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
383	        if (collapsed.isEmpty()) {
384	            return "";
385	        }
386	        String[] tokens = collapsed.split(" ");
387	        StringBuilder sb = new StringBuilder(collapsed.length());
388	        for (int i = 0; i < tokens.length; i++) {
389	            if (i > 0) {
390	                sb.append(' ');
391	            }
392	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
393	        }
394	        return sb.toString();
395	    }
396	
397	    /**
398	     * Derive the stable household identifier shared by owners with the same normalized last name
399	     * and address. It is a deterministic function of those two values, so every member of a
400	     * household independently derives the same identifier: the first 12 upper-case hex characters
401	     * of {@code SHA-256(normalizedLastName + '\n' + normalizedAddress)}.
402	     */
403	    private static String householdId(String normalizedLastName, String normalizedAddress) {
404	        try {
405	            byte[] digest = MessageDigest.getInstance("SHA-256")
406	                .digest((normalizedLastName + "\n" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
407	            StringBuilder sb = new StringBuilder(digest.length * 2);
408	            for (byte b : digest) {
409	                sb.append(String.format("%02x", b));
410	            }
411	            return sb.substring(0, 12).toUpperCase();
412	        }
413	        catch (NoSuchAlgorithmException e) {
414	            throw new IllegalStateException("SHA-256 not available", e);
415	        }
416	    }
417	
418	    /**
419	     * Derive the identity key into which all duplicate detection is consolidated:
420	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. A null email or
421	     * household id contributes an empty segment. Two owners are duplicates only when their whole
422	     * identity keys are equal.
423	     */
424	    private static String identityKey(String telephone, String email, String householdId) {
425	        return (telephone == null ? "" : telephone)
426	            + "|" + (email == null ? "" : email)
427	            + "|" + (householdId == null ? "" : householdId);
428	    }
429	
430	    /**
431	     * Count the existing owners that share the given first and last name, compared
432	     * case-insensitively. Called before the new owner is saved, so the returned value reflects the
433	     * namesakes that already existed at creation time (the new owner itself is not included).
434	     */
435	    private int countNamesakes(String firstName, String lastName) {
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> existing.getFirstName() != null && existing.getLastName() != null)
438	            .filter(existing -> existing.getFirstName().equalsIgnoreCase(firstName)
439	                && existing.getLastName().equalsIgnoreCase(lastName))
440	            .count();
441	    }
442	
443	    /**
444	     * Count the existing owners that already belong to the given household (i.e. carry the same
445	     * non-null householdId). Called after any existing members have been backfilled with the shared
446	     * identifier but before the new owner is saved, so the returned value reflects the members that
447	     * already existed at creation time (the new owner itself is not included). Returns 0 when the
448	     * new owner is not part of any household ({@code householdId} is null).
449	     */
450	    private int countHouseholdMembers(String householdId) {
451	        if (householdId == null) {
452	            return 0;
453	        }
454	        return (int) this.clinicService.findAllOwners().stream()
455	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
456	            .count();
457	    }
458	
459	    /**
460	     * The maximum number of owners a single city may contain. Once a city holds this many owners a
461	     * request to create another owner in it is rejected as a conflict.
462	     */
463	    private static final int MAX_OWNERS_PER_CITY = 50;
464	
465	    /**
466	     * Count the existing owners registered in the given city, compared case-insensitively (as in
467	     * {@link #nextCustomerCode}). Called before the new owner is saved, so the returned value
468	     * reflects the owners that already existed at creation time.
469	     */
470	    private int countOwnersInCity(String city) {
471	        return (int) this.clinicService.findAllOwners().stream()
472	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
473	            .count();
474	    }
475	
476	    /**
477	     * The maximum number of owners that may be created on a single day. Once this many owners
478	     * already carry a given day's registration date, a request to create another owner that day is
479	     * rejected with a 429.
480	     */
481	    private static final int MAX_OWNERS_PER_DAY = 100;
482	
483	    /**
484	     * The number of owners that may be created on a single day before the bulk-signup warning is
485	     * flagged. Once more than this many owners already carry a given day's registration date, a
486	     * newly created owner is flagged with {@code bulkSignupWarning} set true.
487	     */
488	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
489	
490	    /**
491	     * Count the existing owners whose registration date is the given day. Called before the new
492	     * owner is saved, so the returned value reflects the owners that already existed at creation
493	     * time.
494	     */
495	    private int countOwnersRegisteredOn(LocalDate date) {
496	        return (int) this.clinicService.findAllOwners().stream()
497	            .filter(existing -> date.equals(existing.getRegistrationDate()))
498	            .count();
499	    }
500	
501	    /**
502	     * Roll a date forward onto a business day: a Saturday or Sunday is advanced to the following
503	     * Monday, while a weekday is returned unchanged. Used so the effective registration date (whether
504	     * supplied or defaulted) always falls on a business day.
505	     */
506	    private static LocalDate toBusinessDay(LocalDate date) {
507	        return switch (date.getDayOfWeek()) {
508	            case SATURDAY -> date.plusDays(2);
509	            case SUNDAY -> date.plusDays(1);
510	            default -> date;
511	        };
512	    }
513	
514	    /**
515	     * Build the customer code for a new owner: {@code '<REGION>-<HASH8>'} where REGION is the region
516	     * derived from the owner's postcode/city and HASH8 is the first 8 upper-case hex characters of
517	     * {@code SHA-256(normalizedTelephone + lastName)} (e.g. {@code 'NSW-1A2B3C4D'}).
518	     */
519	    private static String customerCode(String region, String normalizedTelephone, String lastName) {
520	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
521	    }
522	
523	    /**
524	     * First 8 upper-case hex characters of {@code SHA-256(input)}.
525	     */
526	    private static String hash8(String input) {
527	        try {
528	            byte[] digest = MessageDigest.getInstance("SHA-256")
529	                .digest(input.getBytes(StandardCharsets.UTF_8));
530	            StringBuilder sb = new StringBuilder(digest.length * 2);
531	            for (byte b : digest) {
532	                sb.append(String.format("%02x", b));
533	            }
534	            return sb.substring(0, 8).toUpperCase();
535	        }
536	        catch (NoSuchAlgorithmException e) {
537	            throw new IllegalStateException("SHA-256 not available", e);
538	        }
539	    }
540	
541	    /**
542	     * Derive the owner's region, preferring the postcode: look up the region by postcode range first
543	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), then fall back to the city-to-region table
544	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD) when the postcode is absent or in no known
545	     * range. Returns {@code 'UNKNOWN'} when neither source resolves a region. This mirrors the
546	     * mapper's locality derivation, so the customer code's region segment and the owner's locality
547	     * always agree.
548	     */
549	    private static String deriveRegion(String postcode, String city) {
550	        if (postcode != null && postcode.matches("\\d{4}")) {
551	            int value = Integer.parseInt(postcode);
552	            for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
553	                int[] range = entry.getValue();
554	                if (value >= range[0] && value <= range[1]) {
555	                    return entry.getKey();
556	                }
557	            }
558	        }
559	        if (city == null) {
560	            return "UNKNOWN";
561	        }
562	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
563	    }
564	
565	    /**
566	     * The fixed city-to-region table used to validate a supplied postcode against the owner's city
567	     * (Sydney-&gt;NSW, Melbourne-&gt;VIC, Brisbane-&gt;QLD). A city not present here has no known region
568	     * and accepts any 4-digit postcode.
569	     */
570	    private static final Map<String, String> CITY_REGION = Map.of(
571	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
572	
573	    /**
574	     * The fixed region-to-postcode ranges (inclusive): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
575	     * Each entry is a two-element {@code {low, high}} array.
576	     */
577	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
578	        "NSW", new int[] {2000, 2099},
579	        "VIC", new int[] {3000, 3099},
580	        "QLD", new int[] {4000, 4099});
581	
582	    /**
583	     * Validate an optional owner postcode. Does nothing when no postcode was supplied (the field is
584	     * optional and the request contract stays backward-compatible). When supplied it must be exactly
585	     * 4 digits and, if the city maps to a known region, must fall within that region's inclusive
586	     * range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
587	     * 4-digit postcode. A malformed or out-of-range postcode throws an
588	     * {@link InvalidOwnerFieldsException} so the request is rejected with a 400.
589	     */
590	    private static void validatePostcode(String city, String postcode) {
591	        if (postcode == null || postcode.isEmpty()) {
592	            return;
593	        }
594	        if (!postcode.matches("\\d{4}")) {
595	            throw new InvalidOwnerFieldsException(List.of("postcode"));
596	        }
597	        String region = city == null ? null : CITY_REGION.get(city);
598	        if (region == null) {
599	            return;
600	        }
601	        int[] range = REGION_POSTCODES.get(region);
602	        int value = Integer.parseInt(postcode);
603	        if (value < range[0] || value > range[1]) {
604	            throw new InvalidOwnerFieldsException(List.of("postcode"));
605	        }
606	    }
607	
608	    /**
609	     * Required national-number length for each E.164 country calling code we validate: a
610	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'} (NANP) number
611	     * carries 10. Country codes not listed here are accepted at any (generally valid) length.
612	     */
613	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of(
614	        "1", 10,
615	        "61", 9);
616	
617	    /**
618	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
619	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
620	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
621	     * The result must be a {@code '+'} followed by 8 to 15 digits, and for a recognised country code
622	     * its national-number length must match ({@code '+61'} requires 9 national digits, {@code '+1'}
623	     * requires 10); otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is
624	     * rejected with a 400.
625	     */
626	    private static String toE164(String raw) {
627	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
628	        boolean hasCountryCode = cleaned.startsWith("+");
629	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
630	        if (!digits.matches("\\d+")) {
631	            throw new InvalidOwnerFieldsException(List.of("telephone"));
632	        }
633	        if (!hasCountryCode) {
634	            if (digits.startsWith("0")) {
635	                digits = digits.substring(1);
636	            }
637	            digits = "61" + digits;
638	        }
639	        if (digits.length() < 8 || digits.length() > 15) {
640	            throw new InvalidOwnerFieldsException(List.of("telephone"));
641	        }
642	        // For a recognised country code, the national number (the digits after the code) must be
643	        // exactly the expected length for that country. Match the longest known code so a shorter
644	        // code that is a prefix of another cannot mask it.
645	        for (int codeLength = 3; codeLength >= 1; codeLength--) {
646	            if (digits.length() <= codeLength) {
647	                continue;
648	            }
649	            String countryCode = digits.substring(0, codeLength);
650	            Integer requiredNationalLength = NATIONAL_NUMBER_LENGTHS.get(countryCode);
651	            if (requiredNationalLength != null) {
652	                if (digits.length() - codeLength != requiredNationalLength) {
653	                    throw new InvalidOwnerFieldsException(List.of("telephone"));
654	                }
655	                break;
656	            }
657	        }
658	        return "+" + digits;
659	    }
660	
661	    /**
662	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
663	     * and a domain with at least one dot-separated label, none of which contain whitespace or
664	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
665	     */
666	    private static final Pattern EMAIL_PATTERN =
667	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
668	
669	    /**
670	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
671	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
672	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
673	     * 400. A valid address is returned lower-cased.
674	     */
675	    private static String normalizeEmail(String email) {
676	        if (email == null || email.isEmpty()) {
677	            return null;
678	        }
679	        String trimmed = email.trim();
680	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
681	            throw new InvalidOwnerFieldsException(List.of("email"));
682	        }
683	        return trimmed.toLowerCase();
684	    }
685	}
